import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/introduction.md","filePath":"src/guide/introduction.md"}'),i={name:"guide/introduction.md"};function n(s,e,u,d,c,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Naia est la plateforme de gestion de projets d&#39;<strong>edPage group</strong> : suivi des phases et jalons, documents et livrables, signature électronique, facturation et paiement en ligne, et messagerie intégrée, pour tous les acteurs d&#39;un projet — clients, équipe interne, partenaires externes et apporteurs d&#39;affaires.</p><p>Ce guide est organisé par rôle : chaque profil n&#39;a accès qu&#39;à ce qui le concerne, donc chaque page couvre exactement ce que vous verrez dans votre propre espace.</p><h2 id="les-roles-sur-naia" tabindex="-1">Les rôles sur Naia <a class="header-anchor" href="#les-roles-sur-naia" aria-label="Permalink to &quot;Les rôles sur Naia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rôle</th><th>Ce qu&#39;il fait sur Naia</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Client</strong></td><td>Suit l&#39;avancement de son projet, valide les livrables, règle ses factures</td><td><a href="./client.html">Guide Client</a></td></tr><tr><td><strong>Partenaire</strong></td><td>Exécute des tâches confiées par un chef de projet, dépose ses factures</td><td><a href="./partenaire.html">Guide Partenaire</a></td></tr><tr><td><strong>Apporteur d&#39;affaires</strong></td><td>Suit le portefeuille de clients qu&#39;il a apportés et ses commissions</td><td><a href="./apporteur-affaires.html">Guide Apporteur d&#39;affaires</a></td></tr><tr><td><strong>Chef de projet</strong></td><td>Pilote un ou plusieurs projets de bout en bout</td><td><a href="./chef-projet-collaborateurs.html">Guide Chef de projet &amp; Collaborateurs</a></td></tr><tr><td><strong>Collaborateur</strong></td><td>Exécute des missions techniques (développement, conseil, cybersécurité…)</td><td><a href="./chef-projet-collaborateurs.html">Guide Chef de projet &amp; Collaborateurs</a></td></tr><tr><td><strong>Administrateur</strong></td><td>Gère les comptes, la facturation et la sécurité de la plateforme</td><td><a href="./administrateur.html">Guide Administrateur</a></td></tr><tr><td><strong>Direction</strong></td><td>Consulte une vue d&#39;ensemble de toute l&#39;activité, décide du blocage pour impayé</td><td><a href="./direction.html">Guide Direction</a></td></tr><tr><td><strong>Contributeur externe</strong></td><td>Membre d&#39;un pôle (Commercial, Support, RH, Facturation) qui transmet ses demandes à Naia</td><td><a href="./contributeur-externe.html">Guide Contributeur externe</a></td></tr></tbody></table><p>Un compte n&#39;a jamais qu&#39;un seul rôle à la fois — les permissions et le contenu du tableau de bord s&#39;adaptent automatiquement.</p><h2 id="se-connecter" tabindex="-1">Se connecter <a class="header-anchor" href="#se-connecter" aria-label="Permalink to &quot;Se connecter&quot;">​</a></h2><p>Naia fonctionne uniquement sur invitation : il n&#39;existe pas d&#39;inscription libre. Vous recevez un e-mail d&#39;invitation contenant un lien pour activer votre compte et choisir votre mot de passe. Une fois le compte activé, vous vous connectez depuis la page de connexion avec votre adresse e-mail et ce mot de passe.</p><p>Si vous n&#39;avez pas reçu d&#39;invitation mais devriez avoir accès à un projet, contactez la personne qui aurait dû vous inviter (votre chef de projet, ou votre apporteur d&#39;affaires si vous êtes client) — voir aussi la page <a href="./support.html">Besoin d&#39;aide ?</a>.</p><h2 id="securite-du-compte" tabindex="-1">Sécurité du compte <a class="header-anchor" href="#securite-du-compte" aria-label="Permalink to &quot;Sécurité du compte&quot;">​</a></h2><p>Depuis <strong>Paramètres &gt; Sécurité</strong>, vous pouvez :</p><ul><li>changer votre mot de passe ;</li><li>activer l&#39;authentification à deux facteurs (2FA), fortement recommandée et proposée automatiquement aux administrateurs à leur connexion.</li></ul><h2 id="notifications-et-messagerie" tabindex="-1">Notifications et messagerie <a class="header-anchor" href="#notifications-et-messagerie" aria-label="Permalink to &quot;Notifications et messagerie&quot;">​</a></h2><p>Vous êtes notifié automatiquement (icône cloche en haut de l&#39;écran) aux étapes clés qui vous concernent : jalon atteint, livrable soumis, document en attente de validation, échéance de facturation due, retard signalé. Chaque projet dispose aussi d&#39;une messagerie intégrée pour échanger avec les autres intervenants sans sortir de la plateforme.</p><h2 id="langue" tabindex="-1">Langue <a class="header-anchor" href="#langue" aria-label="Permalink to &quot;Langue&quot;">​</a></h2><p>Naia est disponible en français et en anglais. Le sélecteur de langue se trouve en haut à droite de l&#39;écran, sur toutes les pages.</p>',16)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
